/** Returns the zero-based GPIO port encoded in a pin. */
#define PIN_PORT(pin) ((unsigned)(pin) >> 5u)
/** Returns the zero-based pin index within its GPIO port. */
#define PIN_INDEX(pin) ((unsigned)(pin) & 0x1fu)

